export function extraQuestions(row) {
  const out = [];

  TRACKS.forEach((track) => {
    APTITUDE.forEach((item, index) => {
      out.push(row(`${track}-ap-x${index + 1}`, track, "aptitude", item[0], item[1], item[2], item[3]));
    });
    HR.forEach((item, index) => {
      out.push(row(`${track}-hr-x${index + 1}`, track, "hr", item[0], item[1], item[2], item[3]));
    });
    (CODING[track] || []).forEach((item, index) => {
      out.push(row(`${track}-co-x${index + 1}`, track, "coding", item[0], item[1], item[2], item[3]));
    });
    (TECHNICAL[track] || []).forEach((item, index) => {
      out.push(row(`${track}-te-x${index + 1}`, track, "technical", item[0], item[1], item[2], item[3]));
    });
  });

  return out;
}
